  /** helper function to set the values of all input ports.
   * @param odd_engine_assessment payload for data port odd_engine_assessment
   * @param even_engine_assessment payload for data port even_engine_assessment
   * @param configuration_assessment payload for data port configuration_assessment
   */
  def put_concrete_inputs(odd_engine_assessment : Power_Propulsion_Availability_Supervisor.EnginePairAssessment.Type,
                          even_engine_assessment : Power_Propulsion_Availability_Supervisor.EnginePairAssessment.Type,
                          configuration_assessment : Power_Propulsion_Availability_Supervisor.ConfigurationAssessment.Type): Unit = {
    put_odd_engine_assessment(odd_engine_assessment)
    put_even_engine_assessment(even_engine_assessment)
    put_configuration_assessment(configuration_assessment)
  }


  /** helper function to check PropulsionEvidenceComposer_supervisor_process_propulsion_evidence_composer's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param propulsion_assessment method that will be called with the value of the outgoing data
   *        port 'propulsion_assessment'.
   */
  def check_concrete_output(propulsion_assessment: Power_Propulsion_Availability_Supervisor.PropulsionAssessment.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val propulsion_assessmentValue: Power_Propulsion_Availability_Supervisor.PropulsionAssessment.Type = get_propulsion_assessment().get
    if(!propulsion_assessment(propulsion_assessmentValue)) {
      testFailures = testFailures :+ st"'propulsion_assessment' did not match expected: value of the outgoing data port is ${propulsion_assessmentValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_odd_engine_assessment(value : Power_Propulsion_Availability_Supervisor.EnginePairAssessment.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_propulsion_evidence_composer.operational_api.odd_engine_assessment_Id, Power_Propulsion_Availability_Supervisor.EnginePairAssessment_Payload(value))
  }

  // setter for in DataPort
  def put_even_engine_assessment(value : Power_Propulsion_Availability_Supervisor.EnginePairAssessment.Type): Unit = {
