  // getter for out DataPort
  def get_propulsion_assessment(): Option[Power_Propulsion_Availability_Supervisor.PropulsionAssessment.Type] = {
    val value: Option[Power_Propulsion_Availability_Supervisor.PropulsionAssessment.Type] = get_propulsion_assessment_payload() match {
