      case Some(v) => halt(s"Unexpected payload on port propulsion_assessment.  Expecting 'Power_Propulsion_Availability_Supervisor.PropulsionAssessment_Payload' but received ${v}")
      case _ => None[Power_Propulsion_Availability_Supervisor.PropulsionAssessment.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_propulsion_assessment_payload(): Option[Power_Propulsion_Availability_Supervisor.PropulsionAssessment_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_propulsion_evidence_composer.initialization_api.propulsion_assessment_Id).asInstanceOf[Option[Power_Propulsion_Availability_Supervisor.PropulsionAssessment_Payload]]
